    } catch (_) { return false; }
  }

  function safeSlug(val) {
    return String(val || 'item').replace(/[^A-Za-z0-9_-]+/g, '_').slice(0, 48);
  }

  function extractTags(caption, prefix) {
    if (!caption) return [];
