  var req = $('CODE | Validate & Safeguard').item.json;
  var sbUrlCfg = readCfg('SUPABASE_URL', 'https://cdgwdlhesgcxmswsamrj.supabase.co');
  var sbKeyCfg = readCfg('SUPABASE_SERVICE_ROLE_KEY', '');
  var dlUrlCfg = readCfg('DOWNLOADER_BASE_URL', 'https://instagram-downloader-psi-one.vercel.app');
