    return [{ json: { ok: false, error: anyBlocked ? 'n8n $env/secret access denied; configure N8N_BLOCK_ENV_ACCESS_IN_NODE=false or $vars.' : 'Missing required Supabase/Downloader/Cloudinary secrets in n8n.' } }];
