    }
    if (dlRes.statusCode >= 300 || dl.ok !== true || String(dl.status || '').toLowerCase() !== 'ready') {
      return await failCleanly('DOWNLOADER_NOT_READY', 'FETCHING_SOURCE', dl.error || ('Downloader returned status ' + String(dl.status || dlRes.statusCode) + ' (ok=' + String(dl.ok) + ')'));
    }

    var rawItems = Array.isArray(dl.media) ? dl.media : Array.isArray(dl.items) ? dl.items : Array.isArray(dl.assets) ? dl.assets : [];
    if (!rawItems.length && (dl.mediaUrl || dl.downloadUrl || dl.url)) {
