    if (rawItems.length < 1 || rawItems.length > 10) {
      return await failCleanly('INVALID_MEDIA_COUNT', 'VALIDATING_MEDIA', 'Downloader returned ' + rawItems.length + ' items (must be 1-10).');
    }

    var nowMs = Date.now();
    for (var m = 0; m < rawItems.length; m++) {
      var it = rawItems[m] || {};
      var mediaRemoteUrl = String(it.url || it.downloadUrl || it.media_url || it.secure_url || '').trim();
      if (!isSafeHttpsRemoteUrl(mediaRemoteUrl)) {
        return await failCleanly('SSRF_BLOCKED', 'VALIDATING_MEDIA', 'Item ' + m + ' has unsafe or non-HTTPS remote URL.');
      }
