          return await failCleanly('MEDIA_URL_EXPIRED', 'VALIDATING_MEDIA', 'Downloader temporary URL for item ' + m + ' already expired at ' + expRaw + '.');
        }
      }
    }

    await sbRpc('instaops_renew_lock', { p_lock_key: req.lock_key, p_owner_id: workerOwner, p_lease_seconds: 600 });
    if (req.job_id) {
