    }
    await sbRest('PATCH', 'instaops_posts?id=eq.' + encodeURIComponent(req.post_uuid), { status: 'UPLOADING' });

    var sourceId = String(dl.sourceId || dl.source_id || dl.shortcode || postRow.source_id || '');
    var totalBytes = 0;
    var imgCount = 0;
    var vidCount = 0;

    for (var idx = 0; idx < rawItems.length; idx++) {
