      var srcUrl = String(itemObj.url || itemObj.downloadUrl || itemObj.media_url || itemObj.secure_url || '').trim();
      var rawKind = String(itemObj.type || itemObj.media_type || itemObj.kind || dl.mediaType || postRow.media_type || '').toUpperCase();
