      var assetMediaType = isVideo ? 'VIDEO' : 'IMAGE';
      var resType = isVideo ? 'video' : 'image';
      var publicId = 'instaops-v2/' + safeSlug(req.post_id) + '/item_' + idx + '_' + (sourceId ? safeSlug(sourceId) : 'src');
      var ts = String(Math.floor(Date.now() / 1000));
