      var signature = sha1Hex(toSign);
      var formBody = 'file=' + encodeURIComponent(srcUrl)
        + '&public_id=' + encodeURIComponent(publicId)
        + '&timestamp=' + encodeURIComponent(ts)
        + '&api_key=' + encodeURIComponent(cldApiKey)
        + '&signature=' + encodeURIComponent(signature);

      var upRes;
      try {
        upRes = await httpCall({
          method: 'POST',
