        return await failCleanly('CLOUDINARY_UPLOAD_FAILED', 'UPLOADING_MEDIA', 'Upload failed at item ' + idx + ' (' + uploadedAssets.length + ' prior checkpointed): ' + (upErr && upErr.message ? upErr.message : 'network error'));
      }

