      if (upRes.statusCode >= 300 || upBody.error || !upBody.secure_url || !upBody.public_id) {
        var errMsg = upBody.error && upBody.error.message ? upBody.error.message : ('Cloudinary upload failed at index ' + idx + ' (HTTP ' + upRes.statusCode + ')');
        return await failCleanly('CLOUDINARY_UPLOAD_FAILED', 'UPLOADING_MEDIA', errMsg + ' (' + uploadedAssets.length + ' prior checkpointed)');
