        height: upBody.height || null,
        duration: upBody.duration || itemObj.duration || null,
        storage_status: 'ACTIVE',
        error: ''
      });
    }

    var rawCaption = String(dl.caption || dl.text || '');
    var captionStatus = rawCaption ? 'available' : String(dl.captionStatus || dl.caption_status || (dl.caption === '' ? 'empty' : 'unavailable'));
    var effectiveCaption = String(postRow.caption || '').trim() ? String(postRow.caption) : rawCaption;
    var resolvedMediaType = uploadedAssets.length > 1 ? 'CAROUSEL' : (uploadedAssets[0].media_type === 'IMAGE' ? 'IMAGE' : 'REEL');
    var nowIso = new Date().toISOString();

    await sbRpc('instaops_renew_lock', { p_lock_key: req.lock_key, p_owner_id: workerOwner, p_lease_seconds: 300 });
    var postPatch = {
      status: 'DRAFT',
      media_url: uploadedAssets[0].secure_url,
      media_type: resolvedMediaType,
      original_caption: rawCaption,
      caption: effectiveCaption,
      caption_status: captionStatus,
      caption_source: String(dl.captionSource || dl.caption_source || (rawCaption ? 'structured' : 'none')),
      canonical_url: String(dl.canonicalUrl || dl.canonical_url || req.source_instagram_url),
      source_id: sourceId,
      source_username: String(dl.username || dl.sourceUsername || dl.ownerUsername || ''),
      source_kind: String(dl.sourceKind || dl.source_kind || ''),
      hashtags: Array.isArray(dl.hashtags) ? dl.hashtags : extractTags(rawCaption, '#'),
      mentions: Array.isArray(dl.mentions) ? dl.mentions : extractTags(rawCaption, '@'),
      media_count: uploadedAssets.length,
      image_count: imgCount,
      video_count: vidCount,
      source_published_at: dl.publishedAt || dl.source_published_at || '',
      source_like_count: dl.likeCount !== undefined ? dl.likeCount : '',
      source_comment_count: dl.commentCount !== undefined ? dl.commentCount : '',
      source_play_count: dl.playCount !== undefined ? dl.playCount : '',
      source_metadata: dl.metadata || {},
      file_size_bytes: totalBytes,
      extracted_at: nowIso,
      uploaded_at: nowIso,
      error: '',
      error_code: '',
      error_stage: ''
    };

    var fin = await sbRpc('instaops_finalize_extraction', {
      p_post_uuid: req.post_uuid,
      p_post_patch: postPatch,
      p_assets: uploadedAssets,
      p_job_id: req.job_id || '',
      p_request_id: req.request_id || '',
      p_execution_id: req.execution_id || '',
      p_lock_key: req.lock_key,
      p_lock_owner: workerOwner
    });
    if (fin.statusCode >= 300) {
      throw new Error('instaops_finalize_extraction RPC failed (HTTP ' + fin.statusCode + ')');
